window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5eabeac5a19beaaf"]={"versions": [{"id": "FIG-5eabeac5a19beaaf", "releases": ["R4.0.3", "R4.1.3", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Konfigurationsdiagramm des AUTOSAR Classic OS (Multicore-Kontext). Das Schaubild veranschaulicht erlaubte Abhängigkeiten und Zuordnungen zwischen Hardware-Timern, OS-Countern, Alarmen, Schedule-Tables sowie den resultierenden Aktionen (Task-Aktivierung, Event-Setzen, Callback) über zwei getrennte Prozessorkerne (Core-Bereiche, dargestellt als graue Container).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Core-Container (graue Boxen):</strong> Zwei Cores zur Partitionierung von OS-Objekten.\n</li><li><strong>Timer (gestrichelte Rechtecke außerhalb der Cores):</strong> Hardware-Timerquellen. Dargestellt sind dedizierte per-Core-Timer sowie ein gemeinsamer, core-übergreifender Timer.\n</li><li><strong>COUNTER (Rechtecke):</strong> Zähler-Objekte des OS. Ein Teil ist mit dem Symbol <code>⟨S⟩</code> als synchronisierter Zähler (<code>Synchronized counter</code>) gekennzeichnet.\n</li><li><strong>ALARM (Rechtecke):</strong> OS-Alarme, die an genau einen Counter gebunden sind.\n</li><li><strong>SCHEDULE-TABLE (Rechtecke):</strong> Ablaufkalender, die auf einem Counter basieren und mehrere Ablaufpunkte steuern.\n</li><li><strong>Zielaktionen / Entitäten (gestrichelte Kreise):</strong>\n<ul class=\"fig-list\"><li><code>Task</code>: Aktivierung eines Tasks.\n</li><li><code>Event</code>: Setzen eines Events für einen erweiterten Task.\n</li><li><code>Callback</code>: Ausführung einer Alarm-Callback-Routine.\n</li></ul>\n</li><li><strong>Kantenarten:</strong>\n<ul class=\"fig-list\"><li>Durchgezogener Pfeil: Intra-Core-Aktionen (<code>Intra core actions.</code>).\n</li><li>Gestrichelter Pfeil: Inter-Core-Aktionen (<code>Inter core actions.</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Zeitbasis:</strong> Hardware-Timer treiben die OS-Counter an. Ein Timer kann direkt einem lokalen Core-Counter zugeordnet sein oder als gemeinsame Zeitbasis Counter auf mehreren Cores treiben (insbesondere für synchronisierte Counter mit Symbol <code>⟨S⟩</code>).\n</li><li><strong>Zähler-Fortschaltung:</strong> Ein lokaler Counter kann mehrere OS-Objekte bedienen; so treibt ein einzelner Counter beispielsweise parallel einen ALARM und eine SCHEDULE-TABLE auf demselben Core.\n</li><li><strong>Aktionsauslösung intra-core:</strong>\n<ul class=\"fig-list\"><li>Ein Alarm oder eine Schedule-Table kann Tasks aktivieren oder Events setzen, die auf demselben Core liegen (durchgezogene Pfeile).\n</li><li>Ein Alarm kann eine Callback-Funktion auf demselben Core aufrufen.\n</li><li>Eine Schedule-Table kann parallel mehrere Aktionen (Task, Event) auf demselben Core auslösen.\n</li></ul>\n</li><li><strong>Aktionsauslösung inter-core:</strong>\n<ul class=\"fig-list\"><li>Ein ALARM auf Core 0 kann einen Task auf Core 1 aktivieren (gestrichelter Pfeil).\n</li><li>Ein ALARM auf Core 1 kann ein Event auf Core 0 setzen.\n</li><li>Eine SCHEDULE-TABLE auf Core 1 kann sowohl lokale Tasks/Events ansteuern als auch kernübergreifend Tasks und Events auf Core 0 auslösen.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zulässige Multi-Core-Konfigurationen:</strong> Counter, Alarme und Schedule-Tables sind statisch an einen Core gebunden. Die ausgelösten Aktionen dürfen jedoch die Core-Grenzen überschreiten (Cross-Core Task Activation / Event Setting).\n</li><li><strong>Callbacks:</strong> Alarm-Callbacks verbleiben streng kernlokal (nur als Intra-Core-Aktion dargestellt).\n</li><li><strong>Synchronisation:</strong> Synchronisierte Zähler (<code>Synchronized counter</code> mit Kennzeichnung <code>⟨S⟩</code>) können durch eine gemeinsame externe oder kernübergreifende Timer-Referenz betrieben werden, um kernübergreifend koordinierte Schedule-Tables zu realisieren.\n</li></ul>"}, {"id": "FIG-b94ae8392879c148", "releases": ["R4.2.2", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Konfigurationsdiagramm des AUTOSAR Classic OS (Multicore-Kontext). Das Schaubild veranschaulicht erlaubte Abhängigkeiten und Zuordnungen zwischen Hardware-Timern, OS-Countern, Alarmen, Schedule-Tables sowie den resultierenden Aktionen (Task-Aktivierung, Event-Setzen, Callback) über zwei getrennte Prozessorkerne (Core-Bereiche, dargestellt als graue Container).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Core-Container (graue Boxen):</strong> Zwei Cores zur Partitionierung von OS-Objekten.\n</li><li><strong>Timer (gestrichelte Rechtecke außerhalb der Cores):</strong> Hardware-Timerquellen. Dargestellt sind dedizierte per-Core-Timer sowie ein gemeinsamer, core-übergreifender Timer.\n</li><li><strong>COUNTER (Rechtecke):</strong> Zähler-Objekte des OS. Ein Teil ist mit dem Symbol <code>⟨S⟩</code> als synchronisierter Zähler (<code>Synchronized counter</code>) gekennzeichnet.\n</li><li><strong>ALARM (Rechtecke):</strong> OS-Alarme, die an genau einen Counter gebunden sind.\n</li><li><strong>SCHEDULE-TABLE (Rechtecke):</strong> Ablaufkalender, die auf einem Counter basieren und mehrere Ablaufpunkte steuern.\n</li><li><strong>Zielaktionen / Entitäten (gestrichelte Kreise):</strong>\n<ul class=\"fig-list\"><li><code>Task</code>: Aktivierung eines Tasks.\n</li><li><code>Event</code>: Setzen eines Events für einen erweiterten Task.\n</li><li><code>Callback</code>: Ausführung einer Alarm-Callback-Routine.\n</li></ul>\n</li><li><strong>Kantenarten:</strong>\n<ul class=\"fig-list\"><li>Durchgezogener Pfeil: Intra-Core-Aktionen (<code>Intra core actions.</code>).\n</li><li>Gestrichelter Pfeil: Inter-Core-Aktionen (<code>Inter core actions.</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Zeitbasis:</strong> Hardware-Timer treiben die OS-Counter an. Ein Timer kann direkt einem lokalen Core-Counter zugeordnet sein oder als gemeinsame Zeitbasis Counter auf mehreren Cores treiben (insbesondere für synchronisierte Counter mit Symbol <code>⟨S⟩</code>).\n</li><li><strong>Zähler-Fortschaltung:</strong> Ein lokaler Counter kann mehrere OS-Objekte bedienen; so treibt ein einzelner Counter beispielsweise parallel einen ALARM und eine SCHEDULE-TABLE auf demselben Core.\n</li><li><strong>Aktionsauslösung intra-core:</strong>\n<ul class=\"fig-list\"><li>Ein Alarm oder eine Schedule-Table kann Tasks aktivieren oder Events setzen, die auf demselben Core liegen (durchgezogene Pfeile).\n</li><li>Ein Alarm kann eine Callback-Funktion auf demselben Core aufrufen.\n</li><li>Eine Schedule-Table kann parallel mehrere Aktionen (Task, Event) auf demselben Core auslösen.\n</li></ul>\n</li><li><strong>Aktionsauslösung inter-core:</strong>\n<ul class=\"fig-list\"><li>Ein ALARM auf Core 0 kann einen Task auf Core 1 aktivieren (gestrichelter Pfeil).\n</li><li>Ein ALARM auf Core 1 kann ein Event auf Core 0 setzen.\n</li><li>Eine SCHEDULE-TABLE auf Core 1 kann sowohl lokale Tasks/Events ansteuern als auch kernübergreifend Tasks und Events auf Core 0 auslösen.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zulässige Multi-Core-Konfigurationen:</strong> Counter, Alarme und Schedule-Tables sind statisch an einen Core gebunden. Die ausgelösten Aktionen dürfen jedoch die Core-Grenzen überschreiten (Cross-Core Task Activation / Event Setting).\n</li><li><strong>Callbacks:</strong> Alarm-Callbacks verbleiben streng kernlokal (nur als Intra-Core-Aktion dargestellt).\n</li><li><strong>Synchronisation:</strong> Synchronisierte Zähler (<code>Synchronized counter</code> mit Kennzeichnung <code>⟨S⟩</code>) können durch eine gemeinsame externe oder kernübergreifende Timer-Referenz betrieben werden, um kernübergreifend koordinierte Schedule-Tables zu realisieren.\n</li></ul>"}], "trans": [{"from": "FIG-5eabeac5a19beaaf", "to": "FIG-b94ae8392879c148", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b94ae8392879c148", "to": "FIG-5eabeac5a19beaaf", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
